import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter - only allows alphanumeric and spaces in 'name' field
    private static final Pattern NAME_PATTERN = Pattern.compile("^[a-zA-Z0-9 ]{1,64}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate name-like fields
        if (department != null && !NAME_PATTERN.matcher(department).matches()) {
            resp.sendError(400, "Invalid department name");
            return;
        }

        // Validate sort direction
        if (sortDir != null && !sortDir.equalsIgnoreCase("ASC") && !sortDir.equalsIgnoreCase("DESC")) {
            sortDir = "ASC";
        }

        // Build query based on report type
        String baseQuery;
        switch (reportType) {
            case "summary":
                baseQuery = "SELECT department, COUNT(*) as cnt, SUM(amount) as total FROM transactions WHERE tx_date BETWEEN ? AND ?";
                break;
            case "detail":
                baseQuery = "SELECT id, department, description, amount, tx_date FROM transactions WHERE tx_date BETWEEN ? AND ?";
                break;
            default:
                resp.sendError(400, "Unknown report type");
                return;
        }

        if (department != null) {
            baseQuery += " AND department = ?";
        }

        if (reportType.equals("summary")) {
            baseQuery += " GROUP BY department";
        }

        // Sort column - validated against whitelist... but sortCol used directly
        if (sortCol != null) {
            // Developer intended to whitelist but forgot to actually check
            baseQuery += " ORDER BY " + sortCol + " " + sortDir;
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, startDate);
            stmt.setString(2, endDate);
            if (department != null) {
                stmt.setString(3, department);
            }

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            JSONObject response = new JSONObject();
            response.put("status", "ok");
            response.put("count", results.length());
            response.put("data", results);
            out.print(response.toString());

        } catch (SQLException e) {
            JSONObject error = new JSONObject();
            error.put("status", "error");
            error.put("message", "Database error occurred");
            out.print(error.toString());
            resp.setStatus(500);
        }
    }
}
